import Foundation

extension AssemblyAIClient {
    /// One paid submit. A lost or unreadable reply is resolved only from the
    /// newest account page, by the exact URL returned for this upload.
    func submit(_ request: TranscriptRequest) throws -> String {
        var post = self.request("POST", path: "/v2/transcript")
        post.setValue("application/json", forHTTPHeaderField: "content-type")
        post.httpBody = try JSONEncoder().encode(request)
        let reply = send(post)
        if let failure = classify(reply) {
            switch failure {
            case .noNetwork, .timedOut, .server, .malformed:
                return try recoverSubmission(audioURL: request.audioURL)
            default:
                throw failure
            }
        }
        if let response = try? JSONDecoder().decode(TranscriptResponse.self, from: reply.data),
            isSendableIdentifier(response.id)
        {
            return response.id
        }
        return try recoverSubmission(audioURL: request.audioURL)
    }

    private struct SubmissionList: Decodable {
        let transcripts: [SubmissionListItem]
    }

    private struct SubmissionListItem: Decodable {
        let id: String
        let audioURL: String

        private enum CodingKeys: String, CodingKey {
            case id
            case audioURL = "audio_url"
        }
    }

    /// A look either establishes one safe id, asks for another bounded look,
    /// or refuses. No row is retained and no unrelated id is requested.
    private func recoverSubmission(audioURL: URL) throws -> String {
        for look in 0..<max(1, tuning.submitRecoveryAttempts) {
            if look > 0 { sleep(tuning.submitRecoveryDelay, cancel: nil) }
            var get = request("GET", path: "/v2/transcript", query: "limit=200")
            get.timeoutInterval = tuning.submitRecoveryTimeout
            let reply = send(get)
            if let failure = classify(reply) {
                if case .keyRefused(let code) = failure {
                    throw ClientError.submissionUnresolved(authenticationStatus: code)
                }
                if failure.isRetriable || failure == .malformed("the request answered nothing at all") {
                    continue
                }
                throw ClientError.submissionUnresolved(authenticationStatus: nil)
            }
            guard let page = try? JSONDecoder().decode(SubmissionList.self, from: reply.data) else {
                continue
            }
            let matching = page.transcripts.filter { $0.audioURL == audioURL.absoluteString }
            if matching.contains(where: { !isSendableIdentifier($0.id) }) {
                throw ClientError.submissionUnresolved(authenticationStatus: nil)
            }
            let ids = Set(matching.map(\.id))
            if ids.count == 1, let id = ids.first { return id }
            if ids.count > 1 {
                throw ClientError.submissionUnresolved(authenticationStatus: nil)
            }
        }
        throw ClientError.submissionUnresolved(authenticationStatus: nil)
    }
}
import Foundation

/// AssemblyAI's wire vocabulary: what a transcript is ASKED for
/// (`TranscriptOptions`, `TranscriptRequest`), what comes back
/// (`TranscriptResponse`, `TranscriptWord`), and `JSONValueRange`, the
/// one tool that lets a served `words` array be carried through this app byte
/// for byte.
///
/// It is beside `AssemblyAIClient.swift` and `MediaTranscript.swift` rather
/// than inside either because both are already at the 400-line cap a new file
/// has (app/CLAUDE.md, road map 6 §5h). What gathers here is the VALUES —
/// nothing here speaks HTTP and nothing here touches disk, so a probe reads
/// every one of them with no socket and no cache directory at all.
/// The marker's type moved to `TranscriptStamp.swift`; this file keeps the
/// wire values and the shared optional-key encoder.
///
/// **Snake case is spelled out, never derived.** `JSONEncoder`'s
/// `.convertToSnakeCase` would turn `audioURL` into `audio_url` and
/// `speechModelUsed` into `speech_model_used` correctly and then turn some
/// later `languageID` into `language_id` where the wire says `language_code`:
/// a `CodingKeys` block is the place a reader can check a key against
/// AssemblyAI's documentation one line at a time.
struct TranscriptOptions: Codable, Equatable {
    /// Both models, in AssemblyAI's documented priority order, so R6-8's
    /// fallback can happen and be reported.
    var speechModels: [String]
    /// nil is "detect the language", which is the wire's ABSENT
    /// `language_code` — `TranscriptRequest` is where that absence is
    /// spelled. Here nil encodes as JSON `null`, because this value is also
    /// road map 6 §5b's `requested` block in the cache file, and a cache that
    /// dropped the key could not be told from one written before the key
    /// existed.
    var languageCode: String?
    var speakerLabels: Bool
    /// Up to `AssemblyAIClient.maxKeyterms` terms; empty is the wire's
    /// ABSENT `keyterms_prompt`.
    var keytermsPrompt: [String]
    /// TR-1: fillers ("um", "uh") kept and timed, on every request CT-1 and
    /// later sends; `requested`'s reader takes an absent key as false.
    var disfluencies: Bool = true

    /// What this build asks for, road map 6 §2's documented default pair.
    static let shippedModels = ["universal-3-5-pro", "universal-2"]

    enum CodingKeys: String, CodingKey {
        case speechModels = "speech_models"
        case languageCode = "language_code"
        case speakerLabels = "speaker_labels"
        case keytermsPrompt = "keyterms_prompt"
        case disfluencies = "disfluencies"
    }

    /// EVERY key, always, with nil written as JSON `null`. The synthesized
    /// encoder uses `encodeIfPresent` and would DROP `language_code` when the
    /// language is auto — and this value is road map 6 §5b's `requested`
    /// block inside the cache file and the marker, where a dropped key could
    /// not be told from one written before the key existed.
    func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(speechModels, forKey: .speechModels)
        if let code = languageCode {
            try container.encode(code, forKey: .languageCode)
        } else {
            try container.encodeNil(forKey: .languageCode)
        }
        try container.encode(speakerLabels, forKey: .speakerLabels)
        try container.encode(keytermsPrompt, forKey: .keytermsPrompt)
        try container.encode(disfluencies, forKey: .disfluencies)
    }
}

/// The vocabulary's rules, beside the field they fill. A pure move out of
/// `AgentServer+CloudCaptions.swift` (c1-chrome): the tool and the sheet's
/// Vocabulary field must cap and de-duplicate a person's list the same way,
/// and two spellings of that would be two answers to one question.
extension TranscriptOptions {

    /// `keyterms_prompt`: trimmed, empties dropped, de-duplicated KEEPING
    /// THE FIRST spelling, capped at `AssemblyAIClient.maxKeyterms`.
    ///
    /// First rather than last because the order a caller wrote is the order
    /// of importance it meant, and the cap cuts from the end — a list that
    /// re-ordered itself and then cut would drop terms the caller put first.
    static func keyterms(_ given: [String]) -> [String] {
        var out: [String] = []
        var seen = Set<String>()
        for term in given {
            let trimmed = term.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty, seen.insert(trimmed).inserted else { continue }
            out.append(trimmed)
            if out.count == AssemblyAIClient.maxKeyterms { break }
        }
        return out
    }
}

/// `POST /v2/transcript`'s body: the upload's URL and the options, flattened
/// into ONE object, because that is the shape AssemblyAI's endpoint takes.
///
/// `Encodable` only. Nothing decodes a request — the response is its own
/// type — and a `Decodable` conformance here would be a second, untested
/// spelling of the same keys.
struct TranscriptRequest: Encodable, Equatable {
    let audioURL: URL
    let options: TranscriptOptions

    enum CodingKeys: String, CodingKey {
        case audioURL = "audio_url"
        case speechModels = "speech_models"
        case languageCode = "language_code"
import AVFoundation

// MARK: - Transcriber: extraction

/// The extractor and what is made from it: a RANGE of any audio file written
/// to a mono 16 kHz 16-bit WAV (`extractAudio(url:name:range:to:cancel:)`),
/// the job form that names today's destination and calls it, the FLAC writer
/// C0's q2 chose for the upload, and `extractUpload`, which puts the two
/// together into the file a cloud run sends. `extractSettings` is the one
/// spelling of that format.
///
/// **The job form's behaviour is unchanged, and that is a claim.** The static
/// form is the block that was here verbatim, with the destination and the
/// range lifted out into its two arguments and `range.start` written where
/// the old code wrote the clip's `in`; the job form computes exactly the
/// destination and range the old code computed and calls it. The WAV a given
/// job extracts is byte-identical to the one the baseline tree's code wrote,
/// which is a row of `cloud_captions_probe.py` rather than a hope.
///
/// **The upload is a FLAC and the WAV is its fallback** (road map 6 §5a, §8).
/// C0's q2 measured a FLAC at 48.1% of the WAV's bytes whose decode is
/// sample-for-sample the same audio, with zero word-timing delta from the
/// service. It is written through `AVAudioFile`, NEVER `AVAssetWriter`:
/// `AVAssetWriter` has no `org.xiph.flac` file type on macOS 26 and refuses
/// it as an Objective-C exception, which Swift cannot catch (§3 q2). When the
/// FLAC write refuses for any other reason the WAV goes up instead and the
/// cache file records which was sent.
///
/// The on-device engine is untouched by all of it: it still hands the
/// recogniser the WAV of one clip's source window.
extension Transcriber {

    // MARK: - Extraction

    /// What the recogniser is handed: 16 kHz mono 16-bit LPCM in a `.wav`.
    ///
    /// Mono and 16 kHz because that is what speech recognition works in — a
    /// minute of it is under two megabytes, where the app's own 48 kHz stereo
    /// mix (`ExporterWriter.decodedAudioSettings`) would be eleven — and LPCM
    /// because an intermediate should cost no generation of its own. The
    /// stereo→mono downmix and the rate conversion are the reader's:
    /// `AVAssetReaderTrackOutput` does both, with no channel layout needed for
    /// one channel out.
    private static let extractSampleRate = 16000

    private static let extractSettings: [String: Any] = [
        AVFormatIDKey: Int(kAudioFormatLinearPCM),
        AVSampleRateKey: extractSampleRate,
        AVNumberOfChannelsKey: 1,
        AVLinearPCMBitDepthKey: 16,
        AVLinearPCMIsFloatKey: false,
        AVLinearPCMIsBigEndianKey: false,
        AVLinearPCMIsNonInterleaved: false,
    ]

    /// Writes the clip's source window to a temporary file and answers where
    /// it went and how long it really is.
    ///
    /// The length is counted in PCM frames rather than read back off the
    /// written asset: `AVAsset.duration` is deprecated in favour of an
        guard writer.status == .completed, frames > 0 else {
            try? FileManager.default.removeItem(at: destination)
            throw TranscribeError.unreadable(name)
        }
        return frames
    }

    // MARK: - What the cloud engine uploads

    /// What was actually sent (road map 6 §5b's `uploaded_format`).
    enum UploadFormat: String {
        case flac
        case wav
    }

    /// A file ready to upload, and everything the cache file needs to say
    /// about it.
    struct Upload: Equatable {
        let url: URL
        let format: UploadFormat
        /// PCM frames extracted, at `extractSampleRate`.
        let frames: Int
        /// `frames / 16000` — what was extracted, not what will be billed:
        /// `audio_duration` rounds UP (§3 q1).
        let seconds: Double
    }

    /// The whole audio track. `.positiveInfinity` rather than a measured
    /// duration on purpose: `AVAsset.duration` and `AVAssetTrack.timeRange`
    /// are deprecated getters whose replacements are `async`, and
    /// `AVAssetReader` clamps a range that runs past the end of the asset, so
    /// the number is not needed at all.
    static let wholeAsset = CMTimeRange(start: .zero, duration: .positiveInfinity)

    /// The WAV, decoded and re-encoded as a 16 kHz mono 16-bit FLAC.
    ///
    /// Streamed in 16 384-frame buffers, never the whole file in memory: the
    /// cloud engine's input is a media's WHOLE audio and ten hours of it is
    /// 1.1 GB of PCM. `cancel` is read per buffer, and `close()` — which
    /// `AVAudioFile` does on deinit — is forced before returning, because
    /// this function's contract is that the file is complete when it answers.
    ///
    /// The four settings are C0's, copied from
    /// `tools/proof/cloud_spike/extract.swift:167`, which is the run that
    /// measured the decode to be sample-for-sample the WAV's.
    static func writeFLAC(fromWAV wav: URL, to destination: URL, cancel: CancelToken) throws {
